<?php require_once 'includes/auth.php'; require_login();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT c.*,u.name,u.email FROM complaints c JOIN users u ON u.id=c.user_id WHERE c.id=?');$st->execute([$id]);$c=$st->fetch();if(!$c) {http_response_code(404);exit('Complaint not found.');}if($_SESSION['user']['role']!=='admin'&&$c['user_id']!=$_SESSION['user']['id']){http_response_code(403);exit('Access denied.');}$page_title='Complaint #'.$c['id'];include 'includes/header.php';$statuses=['Pending','Assigned','In Progress','Resolved'];$current=array_search($c['status'],$statuses); ?><div class="detail-head"><a href="<?= $_SESSION['user']['role']==='admin'?'manage_complaints.php':'my_complaints.php' ?>" class="back-link">← Back to complaints</a><div class="detail-title"><div><div class="eyebrow">COMPLAINT #<?=e($c['id'])?></div><h1><?=e($c['description'])?></h1><p class="muted">Reported <?=e(date('d M Y, g:i A',strtotime($c['created_at'])))?></p></div><?=status_badge($c['status'])?></div></div><div class="detail-grid"><section class="detail-card"><div class="detail-card-head"><h2>Resolution progress</h2></div><div class="timeline"><?php foreach($statuses as $i=>$s):?><div class="timeline-item <?= $i<$current?'done':($i===$current?'current':'') ?>"><div class="timeline-marker"><?=$i<$current?'✓':($i+1)?></div><div><b><?=e($s)?></b><?php if($i===$current):?><span class="muted">Current status</span><?php elseif($i<$current):?><span class="muted">Completed</span><?php else:?><span class="muted">Waiting</span><?php endif;?></div></div><?php if($i<3):?><div class="timeline-line <?= $i<$current?'filled':''?>"></div><?php endif;?><?php endforeach;?></div></section><aside class="detail-card info-card"><h2>Issue details</h2><dl><dt>Category</dt><dd><?=e($c['category'])?></dd><dt>Location</dt><dd><?=e($c['location'])?></dd><dt>Reported by</dt><dd><?=e($c['name'])?></dd><dt>Email</dt><dd><?=e($c['email'])?></dd><?php if($c['assigned_to']):?><dt>Assigned to</dt><dd><?=e($c['assigned_to'])?></dd><?php endif;?></dl><?php if($c['image']):?><div class="image-preview"><img src="uploads/<?=e($c['image'])?>" alt="Complaint attachment"></div><?php endif;?></aside></div><?php if($c['admin_note']):?><section class="note-card"><b>Team note</b><p><?=nl2br(e($c['admin_note']))?></p></section><?php endif;?><?php if($_SESSION['user']['role']==='admin'):?><section class="detail-card admin-update"><h2>Update complaint</h2><form method="post" action="update_status.php"><input type="hidden" name="id" value="<?=$c['id']?>"><div class="update-grid"><label>Status<select name="status"><?php foreach($statuses as $s):?><option <?= $c['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><label>Assigned to<input name="assigned_to" value="<?=e($c['assigned_to']??'')?>" placeholder="e.g. Electrical Team"></label></div><label>Internal / resolution note<textarea name="admin_note" rows="4" placeholder="Add an update for the student..."><?=e($c['admin_note']??'')?></textarea></label>
<button class="btn btn-primary save-update-btn">Save update</button>
</form></section><?php endif;?><?php if(isset($_GET['created'])):?><script>document.addEventListener('DOMContentLoaded',()=>showToast('Complaint submitted successfully.','success'))</script><?php endif;?><?php include 'includes/footer.php'; ?>
